SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF COL_LENGTH('dbo.Products', 'SearchName') IS NULL
    ALTER TABLE dbo.Products ADD SearchName nvarchar(200) NULL;
-- Backfill only missing values; never overwrite what the API normalized. SQL handles precomposed Vietnamese;
-- the API startup backfill (Services/SearchNameBackfill.cs) re-normalizes NFD names, other accents and renames.
EXEC(N'UPDATE dbo.Products SET SearchName = TRANSLATE(LOWER(Name), NCHAR(224)+NCHAR(225)+NCHAR(7841)+NCHAR(7843)+NCHAR(227)+NCHAR(226)+NCHAR(7847)+NCHAR(7845)+NCHAR(7853)+NCHAR(7849)+NCHAR(7851)+NCHAR(259)+NCHAR(7857)+NCHAR(7855)+NCHAR(7863)+NCHAR(7859)+NCHAR(7861)+NCHAR(232)+NCHAR(233)+NCHAR(7865)+NCHAR(7867)+NCHAR(7869)+NCHAR(234)+NCHAR(7873)+NCHAR(7871)+NCHAR(7879)+NCHAR(7875)+NCHAR(7877)+NCHAR(236)+NCHAR(237)+NCHAR(7883)+NCHAR(7881)+NCHAR(297)+NCHAR(242)+NCHAR(243)+NCHAR(7885)+NCHAR(7887)+NCHAR(245)+NCHAR(244)+NCHAR(7891)+NCHAR(7889)+NCHAR(7897)+NCHAR(7893)+NCHAR(7895)+NCHAR(417)+NCHAR(7901)+NCHAR(7899)+NCHAR(7907)+NCHAR(7903)+NCHAR(7905)+NCHAR(249)+NCHAR(250)+NCHAR(7909)+NCHAR(7911)+NCHAR(361)+NCHAR(432)+NCHAR(7915)+NCHAR(7913)+NCHAR(7921)+NCHAR(7917)+NCHAR(7919)+NCHAR(7923)+NCHAR(253)+NCHAR(7925)+NCHAR(7927)+NCHAR(7929)+NCHAR(273), N''aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyyd'') WHERE SearchName IS NULL');
COMMIT;
